{{--
    SPACER PENGGANTI MARGIN
    Dulu footer memakai mt-28 md:mt-40, tapi margin itu transparan sehingga memperlihatkan warna <body>.
    Kalau section terakhir halaman warnanya beda dari <body>, muncul pita "belang".
    Spacer ini warnanya otomatis disamakan dengan section di atasnya (lihat script di bawah footer).
    Untuk memaksa warna tertentu di satu halaman: @section('footer_bg', '#ffffff')
--}}
<style>
    /* Neon emas pada siger: dua lapis drop-shadow (tajam + menyebar) mengikuti bentuk siger */
    .siger-glow {
        filter: drop-shadow(0 0 2px rgba(246, 226, 163, .75))
                drop-shadow(0 0 10px rgba(224, 176, 74, .65))
                drop-shadow(0 0 26px rgba(201, 154, 50, .45));
        animation: sigerNeon 4.5s ease-in-out infinite;
    }
    .siger-glow-kapal { filter: drop-shadow(0 0 4px rgba(224, 176, 74, .7)); }
    /* Aura: cahaya radial di belakang siger */
    .siger-aura {
        background: radial-gradient(ellipse 50% 60% at 50% 100%, rgba(224, 176, 74, .55), rgba(201, 154, 50, .22) 45%, transparent 72%);
        filter: blur(6px);
        animation: sigerAura 4.5s ease-in-out infinite;
    }
    @keyframes sigerNeon {
        0%, 100% { filter: drop-shadow(0 0 2px rgba(246,226,163,.75)) drop-shadow(0 0 10px rgba(224,176,74,.65)) drop-shadow(0 0 26px rgba(201,154,50,.45)); }
        50%      { filter: drop-shadow(0 0 3px rgba(246,226,163,.95)) drop-shadow(0 0 14px rgba(224,176,74,.85)) drop-shadow(0 0 34px rgba(201,154,50,.6)); }
    }
    @keyframes sigerAura { 0%, 100% { opacity: .75; } 50% { opacity: 1; } }
    /* Bulatan aura emas di badan footer */
    .orb-footer {
        background: radial-gradient(circle at 50% 50%, rgba(224,176,74,calc(var(--w,.4))), rgba(201,154,50,calc(var(--w,.4) * .45)) 40%, transparent 70%);
        filter: blur(14px);
        animation: orbMelayang 9s ease-in-out infinite;
        animation-delay: var(--d, 0s);
    }
    .orb-ring {
        border: 1px solid rgba(224,176,74,.55);
        box-shadow: 0 0 10px rgba(224,176,74,.55), 0 0 28px rgba(201,154,50,.35), inset 0 0 12px rgba(224,176,74,.25);
        animation: orbRing 6s ease-in-out infinite;
    }
    @keyframes orbMelayang {
        0%, 100% { transform: translate3d(0,0,0) scale(1);   opacity: .85; }
        50%      { transform: translate3d(0,-10px,0) scale(1.08); opacity: 1; }
    }
    @keyframes orbRing {
        0%, 100% { opacity: .35; transform: scale(1); }
        50%      { opacity: .9;  transform: scale(1.12); }
    }
    @media (prefers-reduced-motion: reduce) {
        .siger-glow, .siger-aura, .orb-footer, .orb-ring { animation: none; }
    }
</style>

