{{-- Samakan warna spacer dengan latar yang TERLIHAT tepat di atas footer --}}
<script>
(function () {
    // Kembalikan 'rgb(...)' bila warna cukup pekat (alpha >= 0.9), selain itu null
    function pekat(c) {
        if (!c || c === 'transparent') return null;
        var m = c.match(/rgba?\(([^)]+)\)/);
        if (!m) return null;
        var p = m[1].split(',').map(function (v) { return parseFloat(v); });
        var a = p.length > 3 ? p[3] : 1;
        return a >= 0.9 ? 'rgb(' + p[0] + ', ' + p[1] + ', ' + p[2] + ')' : null;
    }

    // Cari warna latar elemen yang menutupi titik tepat di atas spacer (di tepi kiri layar,
    // supaya kartu/kontainer di tengah tidak ikut terbaca).
    function warnaDiAtasFooter(sp) {
        var r = sp.getBoundingClientRect();
        var x = 2, y = r.top - 2;
        var warna = null;
        var semua = document.body.getElementsByTagName('*');
        for (var i = 0; i < semua.length; i++) {
            var e = semua[i];
            if (e === sp || sp.contains(e) || e.closest('footer')) continue;
            if (e.tagName === 'SCRIPT' || e.tagName === 'STYLE') continue;
            var b = e.getBoundingClientRect();
            if (b.width === 0 || b.height === 0) continue;
            if (x < b.left || x > b.right || y < b.top || y > b.bottom) continue;
            var cs = getComputedStyle(e);
            if (cs.position === 'fixed' || cs.visibility === 'hidden' || cs.display === 'none') continue;
            var c = pekat(cs.backgroundColor);
            if (c) warna = c;   // yang terakhir di urutan DOM = paling dalam / paling atas
        }
        if (!warna) warna = pekat(getComputedStyle(document.body).backgroundColor)
                         || pekat(getComputedStyle(document.documentElement).backgroundColor);
        return warna;
    }

    function terapkan(sp) {
        var c = getComputedStyle(sp).backgroundColor;
        if (!pekat(c)) c = '#ffffff';
        document.documentElement.style.setProperty('--footer-bg', c);
    }

    function samakanSpacer() {
        var sp = document.getElementById('footer-spacer');
        if (!sp) return;
        if (!sp.dataset.manual) {
            var w = warnaDiAtasFooter(sp);
            if (w) sp.style.backgroundColor = w;
        }
        terapkan(sp);
    }

    document.addEventListener('DOMContentLoaded', samakanSpacer);
    window.addEventListener('load', function () { samakanSpacer(); setTimeout(samakanSpacer, 400); });
    document.addEventListener('livewire:navigated', function () { samakanSpacer(); setTimeout(samakanSpacer, 400); });
    samakanSpacer();
})();
</script>